import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.audio.transcriptions.create({ file: new Uint8Array([1, 2, 3]), model: "string", language: "string", prompt: "string", response_format: "json", temperature: 0, include: ["logprobs"], timestamp_granularities: ["segment"], stream: true, chunking_strategy: "auto", known_speaker_names: ["string"], known_speaker_references: ["string"] });
console.log(result);
